.dm-bws{width:100%;max-width:440px;margin:0 auto;padding:6px}
.dm-bws-h{display:flex;align-items:center;justify-content:space-between;gap:var(--dm-s-3);padding:var(--dm-s-2) 10px 10px}
.dm-bws-ht{display:flex;flex-direction:column;min-width:0}
.dm-bws-ht b{font-weight:500;font-size:14px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.dm-bws-st{font-size:12.5px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.dm-bws-ctl{display:flex;align-items:center;gap:var(--dm-s-1);flex:none}
.dm-bws-take[aria-pressed="true"]{background:var(--dm-accent-bg);color:var(--dm-accent-fg,var(--dm-accent));box-shadow:none}
.dm-bws-win{margin:0 var(--dm-s-1);border-radius:var(--dm-r-in);border:1px solid var(--dm-line);overflow:hidden;transition:border-color .3s}
.dm-bws.dm-you .dm-bws-win{border-color:var(--dm-accent-mark,var(--dm-accent))}
.dm-bws-bar{display:flex;align-items:center;gap:var(--dm-s-2);height:36px;padding:0 var(--dm-s-2) 0 10px;background:var(--dm-wash);border-bottom:1px solid var(--dm-line)}
.dm-bws-dots{display:flex;gap:var(--dm-s-1);flex:none}
.dm-bws-dots i{width:7px;height:7px;border-radius:50%;background:var(--dm-faint)}
.dm-bws-url{flex:1;min-width:0;display:flex;align-items:center;gap:6px;height:24px;padding:0 10px;border-radius:var(--dm-r-pill);background:var(--dm-surface);box-shadow:inset 0 0 0 1px var(--dm-line);font-size:12px;color:var(--dm-fg2)}
.dm-bws-url .dm-i{color:var(--dm-muted)}
.dm-bws-url span{min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.dm-bws-vp{position:relative;height:156px;overflow:hidden;background:var(--dm-surface)}
/* the page itself, drawn small: real words where they matter, grey lines for the rest */
.dm-bws-pg{position:absolute;left:0;right:0;top:0;padding:var(--dm-s-3) 14px;display:flex;flex-direction:column;gap:10px;font-size:12px;color:var(--dm-fg2);transition:transform .8s var(--dm-ease)}
.dm-bws-ln{display:block;height:6px;border-radius:3px;background:var(--dm-chip)}
.dm-bws-nav{display:flex;align-items:center;gap:var(--dm-s-3);font-size:11.5px;color:var(--dm-muted);white-space:nowrap}
.dm-bws-nav b{display:flex;align-items:center;gap:6px;margin-right:auto;font-weight:500;color:var(--dm-fg)}
.dm-bws-nav b::before{content:"";width:12px;height:12px;border-radius:var(--dm-r-xs);background:var(--dm-fg)}
.dm-bws-nav .dm-on{color:var(--dm-fg)}
.dm-bws-hd{font-size:13px;font-weight:500;color:var(--dm-fg)}
.dm-bws-q{display:flex;align-items:center;gap:6px;height:26px;padding:0 10px;border-radius:var(--dm-r-pill);box-shadow:inset 0 0 0 1px var(--dm-line);color:var(--dm-fg);white-space:nowrap;overflow:hidden}
.dm-bws-res{display:flex;flex-direction:column;gap:2px;min-width:0}
.dm-bws-res b{font-weight:500;color:var(--dm-pb);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;align-self:flex-start;max-width:100%}
.dm-bws-res span{font-size:11.5px;color:var(--dm-muted)}
.dm-bws-cta{align-self:flex-start;height:22px;padding:0 10px;display:inline-flex;align-items:center;border-radius:var(--dm-r-pill);background:var(--dm-chip);font-size:11.5px;color:var(--dm-fg2)}
.dm-bws-tb{display:flex;flex-direction:column;border-radius:var(--dm-r-sm);box-shadow:inset 0 0 0 1px var(--dm-line)}
.dm-bws-tb div{display:flex;justify-content:space-between;gap:var(--dm-s-3);padding:5px 10px;border-top:1px solid var(--dm-line)}
.dm-bws-tb div:first-child{border-top:0;font-size:11.5px;color:var(--dm-muted)}
.dm-bws-tb .dm-num{padding:0 var(--dm-s-1);margin:0 -4px;border-radius:var(--dm-r-xs);color:var(--dm-fg);transition:background .3s,color .3s}
/* a price the agent has taken is marked like a highlighter, in the accent fill */
.dm-bws-tb .dm-num.dm-hit{background:var(--dm-accent);color:var(--dm-on-accent)}
/* what the agent is about to press gets a ring, and its own pointer glides there */
.dm-bws-vp .dm-aim{outline:1.5px solid var(--dm-accent-mark,var(--dm-accent));outline-offset:2px;border-radius:var(--dm-r-xs)}
.dm-bws-cur{position:absolute;left:0;top:0;width:14px;height:14px;z-index:2;color:var(--dm-accent-mark,var(--dm-accent));pointer-events:none;opacity:0;transition:transform .7s var(--dm-ease),opacity .2s}
.dm-bws-cur.dm-on{opacity:1}
.dm-bws-cur svg{display:block;width:14px;height:14px;transition:transform .16s var(--dm-ease)}
.dm-bws-cur svg path{fill:currentColor;stroke:var(--dm-surface);stroke-width:1.4;stroke-linejoin:round}
.dm-bws-cur.dm-down svg{transform:scale(.8)}
/* the page's own cookie banner, the thing in the agent's way */
.dm-bws-ck{position:absolute;left:8px;right:8px;bottom:8px;z-index:1;display:flex;align-items:center;gap:6px;padding:6px 6px 6px 10px;border-radius:10px;background:var(--dm-raised);box-shadow:var(--dm-shadow-pop);font-size:12px;color:var(--dm-fg);transform:translateY(calc(100% + 12px));transition:transform .5s var(--dm-ease)}
.dm-bws-ck.dm-on{transform:none}
.dm-bws-ck span{flex:1;min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.dm-bws-ck button{flex:none;height:24px;padding:0 9px;border-radius:var(--dm-r-pill);font-size:11.5px;background:var(--dm-chip);color:var(--dm-fg)}
.dm-bws-ck button+button{background:var(--dm-ink);color:var(--dm-on-ink)}
.dm-bws:not(.dm-you) .dm-bws-ck button{cursor:default}
.dm-bws-steps{list-style:none;margin:0;padding:var(--dm-s-2) 0 0;display:flex;flex-direction:column}
.dm-bws-s{display:flex;align-items:flex-start;gap:10px;padding:6px 10px;font-size:13px;color:var(--dm-muted)}
.dm-bws-s .dm-g{width:16px;height:19.5px;display:grid;place-items:center;flex:none;color:var(--dm-faint)}
.dm-bws-s .dm-g .dm-spin{width:11px;height:11px;color:var(--dm-accent-fg,var(--dm-accent))}
.dm-bws-s.dm-done{color:var(--dm-fg2)}.dm-bws-s.dm-done .dm-g{color:var(--dm-ok)}
.dm-bws-s.dm-run,.dm-bws-s.dm-wait{color:var(--dm-fg)}
.dm-bws-s.dm-wait .dm-g{color:var(--dm-warn)}
.dm-bws.dm-paused .dm-bws-s .dm-g .dm-spin{animation-play-state:paused;color:var(--dm-muted)}
.dm-bws-t{flex:1;min-width:0;display:flex;flex-direction:column}
.dm-bws-t>span{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.dm-bws-t .dm-d{font-size:12px;color:var(--dm-muted)}
.dm-bws-s.dm-wait .dm-d{color:var(--dm-warn)}
.dm-bws-ask{display:flex;flex-wrap:wrap;align-items:center;gap:var(--dm-s-2);margin-top:var(--dm-s-2)}
.dm-bws-sum{display:flex;align-items:center;gap:var(--dm-s-2);margin:var(--dm-s-2) var(--dm-s-1) 2px;padding:10px var(--dm-s-3);border-radius:var(--dm-r-in);background:var(--dm-ok-bg);font-size:13px}
.dm-bws-sum svg{color:var(--dm-ok);flex:none}
.dm-bws-sum span{min-width:0}

